package factories

import (
	"fmt"

	"github.com/vuepher/vuepher/orm"

	"blog/app/models"
)

// NewPostFactory builds a factory for Post records.
//
// Generated by `vuepher make:factory PostFactory`, then filled in with the
// model's own columns.
//
// The index passed to the build function is zero-based and unique, so generated
// values do not collide when a batch is inserted:
//
//	records, err := factories.NewPostFactory(50).Create(db)
func NewPostFactory(count int) *orm.Factory[models.Post] {
	return orm.NewFactory(count, func(i int) models.Post {
		return models.Post{
			Title:     PostTitle(i),
			Body:      PostBody(i),
			Published: i%2 == 0,
		}
	})
}

// PostTitle is a helper kept next to the factory so a seeder and a test produce
// the same style of value.
func PostTitle(index int) string {
	return fmt.Sprintf("Post %d", index+1)
}

// PostBody is the matching body helper. It is long enough to satisfy the
// `required` rule the model declares.
func PostBody(index int) string {
	return fmt.Sprintf("Body for post %d, generated by PostFactory.", index+1)
}
